def solve_change_ways(text):
    tokens = text.split()
    k = int(tokens[0])
    coins = [int(t) for t in tokens[1:1 + k]]
    q = int(tokens[1 + k])
    fares = [int(t) for t in tokens[2 + k:2 + k + q]]
    mod = 1_000_000_007
    top = max(fares)
    ways = [1] + [0] * top
    for c in coins:
        for a in range(c, top + 1):
            ways[a] = (ways[a] + ways[a - c]) % mod
    return '\n'.join(str(ways[f]) for f in fares)

